CREATE OR REPLACE FUNCTION order_outbox() RETURNS trigger AS $$ DECLARE eid uuid:=gen_random_uuid();et text;rk text;farmers text;BEGIN et:=CASE WHEN TG_OP='INSERT' THEN 'OrderCreated' WHEN NEW.status='CONFIRMED' THEN 'OrderConfirmed' WHEN NEW.status='PACKING' THEN 'OrderPackingStarted' WHEN NEW.status='SHIPPING' THEN 'OrderShippingStarted' WHEN NEW.status='DELIVERED' THEN 'OrderDelivered' ELSE 'OrderCancelled' END;rk:=CASE NEW.status WHEN 'CONFIRMED' THEN 'order.confirmed' WHEN 'CANCELLED' THEN 'order.cancelled' ELSE 'order.'||lower(NEW.status) END;SELECT string_agg(DISTINCT farmer_id::text,',') INTO farmers FROM order_items WHERE order_id=NEW.id;INSERT INTO outbox_events(id,aggregate_type,aggregate_id,event_type,event_version,payload,status,created_at)VALUES(eid,'Order',NEW.id::text,et,1,jsonb_build_object('eventId',eid,'eventType',et,'eventVersion',1,'aggregateType','Order','aggregateId',NEW.id::text,'occurredAt',now(),'traceId',gen_random_uuid(),'producer','order-service','routingKey',rk,'payload',jsonb_build_object('orderId',NEW.id,'buyerId',NEW.buyer_id,'farmerIds',coalesce(farmers,''),'deliveryAddress',NEW.delivery_address,'status',NEW.status)),'PENDING',now());RETURN NEW;END$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_order_outbox AFTER INSERT OR UPDATE OF status ON orders FOR EACH ROW EXECUTE FUNCTION order_outbox();
